// Generated by tools/site/build-site.ps1 from tools/site/templates/site.js - do not edit docs/site.js.
//
// The pages are static: every string is already rendered in the page's own language, so there is no
// translation table here. This file handles the theme, the language links and the back-to-top button.
// It holds no language code beyond the three of the shared control (PAGE-STYLE section 4.2) - every link
// carries its own target URL, emitted by the generator from the Core language registry.
//
// Shared state (PAGE-STYLE section 7): `sza-theme` holds exactly dark or light and `sza-lang` exactly
// ru, en or ua, because every product page under this origin reads and writes the same two keys. A
// further locale is never written to `sza-lang`; it is remembered in `streamsplayer-locale` together
// with the shared value current at that moment, and the entry-page redirect in the head honours it only
// while that value is unchanged.
//
// No runtime request (SP-0259, PAGE-STYLE 3.10). The download links, the version and its date are
// rendered into the page at build time from tools/site/release-manifest.json; the SP-0092 resolver that
// asked api.github.com for the latest release is gone, so a rate-limited or script-less visitor gets the
// same working link as everyone else, and the privacy page no longer names that request.

function setThemeMeta(theme) {
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) {
    meta.content = theme === "light" ? "#eef3ea" : "#0a0f0a";
  }
}

function storePreference(key, value) {
  try {
    localStorage.setItem(key, value);
    return true;
  } catch (error) {
    return false;
  }
}

function removePreference(key) {
  try {
    localStorage.removeItem(key);
  } catch (error) {
    // Nothing stored, nothing to remove.
  }
}

function toggleTheme() {
  const nextTheme = document.documentElement.dataset.theme === "light" ? "dark" : "light";
  document.documentElement.dataset.theme = nextTheme;
  storePreference("sza-theme", nextTheme);
  setThemeMeta(nextTheme);
}

document.addEventListener("DOMContentLoaded", () => {
  setThemeMeta(document.documentElement.dataset.theme || "dark");

  const themeButton = document.getElementById("themeButton");
  if (themeButton) {
    themeButton.addEventListener("click", toggleTheme);
  }

  // RU EN UA: remember the choice before the browser follows the link.
  document.querySelectorAll(".seg a[data-lang]").forEach((link) => {
    link.addEventListener("click", () => {
      storePreference("sza-lang", link.dataset.lang);
      removePreference("streamsplayer-locale");
    });
  });

  // A further locale: the shared key keeps its value; only this product's key learns the choice.
  document.querySelectorAll(".language-row a[data-locale]").forEach((link) => {
    link.addEventListener("click", () => {
      let shared = "";
      try {
        shared = localStorage.getItem("sza-lang") || "";
      } catch (error) {
        // Nothing to pair the choice with.
      }
      if (shared === "uk") {
        shared = "ua";
      }
      storePreference("streamsplayer-locale", link.dataset.locale + "@" + (shared === "ru" || shared === "en" || shared === "ua" ? shared : ""));
    });
  });

  const toTop = document.getElementById("toTop");
  if (toTop) {
    toTop.addEventListener("click", () => window.scrollTo({ top: 0, behavior: "smooth" }));
    window.addEventListener("scroll", () => {
      toTop.classList.toggle("show", window.scrollY > 600);
    });
  }
});
